import os; OUT = os.environ.get("OUT", ".")
import json
D = json.load(open("results.json"))
F = [("The model layer is correct.", "Analytic Greeks match central finite differences to 7 significant digits, implied-vol inversion round-trips to 1e-15, and recovered smiles sit 6 bp of vol from ground truth despite 0.2-cent price noise. The SVI fit passes calendar and butterfly checks."),
("Hedging error scales with the square root of the rebalance interval.", "With no costs the P&L std rises from 0.22 (4 hedges a day) to 3.04 (no rehedging), a 14x increase for 252x fewer hedges. Costs fall roughly as 1/sqrt(frequency): at 10 bps they drop from 0.61 to 0.11 per option."),
("More hedging stops paying earlier than you expect.", "One vol point of edge is worth about 0.20 per option. At 10 bps the cost of hedging 4 times a day (0.61) is three times the edge, so the net mean is -0.41. The tail-optimal frequency (best 5% mean) is 4/day at 0 bps, 2/day at 10 bps and 1/day at 25 bps. The mean alone favours almost no hedging, but at a CVaR of -7.7 versus -1.1 that is a naked gamma position, and means above k=32 are within noise (standard error 0.02 to 0.05)."),
("Band rules dominate the calendar once costs are real.", "At 25 bps, Whalley-Wilmott (gamma=2) has a CVaR of -1.61 and a mean of -0.35 against -1.97 and -0.69 for hedging once per 4 steps, at a similar std (0.57 versus 0.52). At 2.5 bps the rules are indistinguishable."),
("Misestimating vol costs risk, not mean.", "With realised vol at 20%, the net mean stays between 0.01 and 0.04 for any hedge vol from 10% to 30%, because quote edge minus cost is first-order independent of the hedge vol. The std is lowest at the right vol (0.44) and rises to 1.16 if you underestimate by 10 points versus 0.72 if you overestimate, so underestimating is the costlier error."),
("Regime shifts widen the distribution by 2.4x without moving the mean.", "Switching from constant 24% to a 15%/30% regime process lifts the std from 0.53 to 1.27 and the CVaR from -1.24 to -2.53 for the same rule. Attribution shows why: gamma loses 2.32 and theta earns 2.47, so the mean is a small difference of two large numbers that decouple path by path."),
("A causal EWMA hedge vol helps the tail modestly.", "It improves CVaR by about 13 to 14% (-2.53 to -2.19 for time-based, -2.22 to -1.91 for WW) and trims std by about 2%, with no change in the mean. Because the mark here is realised-vol based, the vega bucket stays small (0.14)."),
("Limits.", "One ATM 3-month contract, GBM and a two-state Markov vol process, a flat proportional cost model, no market impact or bid-ask on the hedge, marks driven by realised not implied vol, 4,000 paths per scenario, cash settlement with the final hedge unwound at cost. Treat the orderings as robust and the exact break-even frequencies as parameter-specific.")]
html = open("tpl.html").read().replace("/*DATA*/", json.dumps(D, separators=(",", ":"))).replace("<!--FINDINGS-->", "".join(f'<p class="f"><b>{a}</b>{b}</p>' for a, b in F))
open(OUT + "/hedging_lab.html", "w").write(html)
md = "# Options Market Making, Volatility Trading and Dynamic Hedging: Experimental Report\n\n## Setup\nShort or long one ATM European call (S=K=100, T=0.25, r=2%), hedged in shares over 252 steps (4 per day), 4,000 simulated paths per scenario with common random numbers across rules. Quote edge is one vol point (sell at realised+1pt, buy at realised-1pt). Costs are proportional to traded notional, with a final unwind of the hedge.\n\n- Time-based: rebalance every k steps.\n- Threshold: rebalance to delta when |delta error| exceeds a band.\n- Volatility-sensitive: Whalley-Wilmott band, half-width (1.5 kappa S Gamma^2 / gamma)^(1/3), with gamma computed from the current vol estimate (fixed or causal EWMA).\n\nP&L attribution per step: quote edge (initial), delta slippage s(D_opt - D_held)dS, gamma s*0.5*Gamma*dS^2, theta plus cash carry, vega s*Vega*d(sigma_mark), costs, and an exact residual so buckets sum to total.\n\n## Findings\n" + "\n".join(f"{i+1}. **{a}** {b}" for i, (a, b) in enumerate(F)) + "\n\n## Reproduce\n`python run_experiments.py` writes results.json; `python build.py` regenerates this report and the dashboard.\n"
open(OUT + "/REPORT.md", "w").write(md)
